# Disable Windows Tips & Suggestions Write-Host "Disabling Windows tips, tricks, and suggestions..." -ForegroundColor Cyan # Disable tips about Windows Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" -Name "SoftLandingEnabled" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue # Disable suggested tips Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" -Name "SubscribedContent-338389Enabled" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue # Disable tips on lock screen Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" -Name "SubscribedContent-338387Enabled" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue # Disable "Get tips and suggestions when using Windows" Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" -Name "SystemPaneSuggestionsEnabled" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue # Disable suggested apps in Start menu Set-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager" -Name "SubscribedContent-338388Enabled" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue # Remove Tips app Get-AppxPackage -Name "Microsoft.Getstarted" -ErrorAction SilentlyContinue | Remove-AppxPackage -ErrorAction SilentlyContinue # Remove Get Help app Get-AppxPackage -Name "Microsoft.GetHelp" -ErrorAction SilentlyContinue | Remove-AppxPackage -ErrorAction SilentlyContinue Write-Host "Windows tips and suggestions have been disabled." -ForegroundColor Green